select id, customer_id, order_date, discount, shipping_fee, corr(shipping_fee, amount) over (partition by channel) as corr_shipping_fee_amount, lag(shipping_fee, 1) over w_grp as prev_shipping_fee, last_value(shipping_fee, true) over w_grp_2 as last_known_shipping_fee from orders window w_grp as (partition by store_id order by shipping_fee, id), w_grp_2 as (partition by customer_id order by order_date, id rows between unbounded preceding and current row);
